class Solution {
public:
    int minNumberOfFrogs(string croakOfFrogs) {
        int stage[4] = {0, 0, 0, 0};
        int active = 0, answer = 0;
        string order = "croak";
        for (char c : croakOfFrogs) {
            int p = order.find(c);
            if (p == (int)string::npos) return -1;
            if (p == 0) {
                ++stage[0];
                answer = max(answer, ++active);
            } else {
                if (stage[p - 1] == 0) return -1;
                --stage[p - 1];
                if (p == 4) --active;
                else ++stage[p];
            }
        }
        return active == 0 ? answer : -1;
    }
};
